Program Definition Induced : ([B, C]) ⟶ ([A, C]) := {|
  fobj := fun G => G ◯ F;
  fmap := fun _ _ f => {| transform := fun z => transform[f] (F z) |}
|}.   (* Context {A B : Category} {F : A ⟶ B} {C : Category} *)

Class LeftKan := {
  Lan : [A, C] ⟶ [B, C];           (* the left Kan extension functor *)
  lan_adjoint : Lan ⊣ Induced      (* universal property: Lan ⊣ Induced *)
}.

Class RightKan := {
  Ran : [A, C] ⟶ [B, C];           (* the right Kan extension functor *)
  ran_adjoint : Induced ⊣ Ran      (* universal property: Induced ⊣ Ran *)
}.

Program Instance Diagonal_Product_Adjunction (C : Category) `{@Cartesian C} :
  Diagonal_Product C ⊣ ×(C) := {
  adj := fun _ _ => {| to := {| morphism := fun f => fst f △ snd f |}
                     ; from := {| morphism := fun f => (exl ∘ f, exr ∘ f) |} |} }.

Program Instance Diagonal {C : Category} (J : Category) : C ⟶ [J, C] := {
  fobj := fun x => {| fobj := fun _ => x ; fmap := fun _ _ _ => id[x] |};
  fmap := fun _ _ f => {| transform := fun _ => f |} }.

Program Definition Star_Functor `(f : c ~> a) :
  @Slice C a ⟶ @Slice C c := {|
  fobj := λ '(_; h), let pull : Pullback h f := pullbacks h f in
                     (Pull h f pull; pullback_snd h f pull);
  fmap := λ '(a; x) '(b; y) '(g; H), ... (mediator from ump_pullbacks) |}.   (* under Hypothesis pullbacks : ∀ {X Y Z : C} (f : Y ~> Z) (g : X ~> Z), Pullback f g *)

Program Instance Sets_Closed : @Closed Sets _ := {
  exponent_obj := fun x y => {| carrier := SetoidMorphism x y ; is_setoid := @SetoidMorphism_Setoid x y |};
  exp_iso := fun _ _ _ => {| to := (curry) ... ; from := (uncurry) ... |} }.
